const test = require('node:test');
const assert = require('node:assert/strict');
const bcrypt = require('bcryptjs');

// Synthetic fixtures generated by native bcrypt 6 before replacing it.
const fixtures = [
  ['Existing-account-test-42!', '$2b$10$j6/njMmIkE4eoxsuC9q.NuMC6Hcl2FlX3S7C1k/6HujfIEepe4BQa'],
  ['Unicode-🔒-परीक्षण', '$2b$10$E1A0yWjqIKkbrOiRxf9J1us0N/oWRHyS64VekzpJT7XXlNG.1wKcG'],
];

test('existing native bcrypt password hashes remain valid', async () => {
  for (const [password, hash] of fixtures) {
    assert.equal(await bcrypt.compare(password, hash), true);
    assert.equal(await bcrypt.compare(password + 'wrong', hash), false);
    assert.equal(await bcrypt.hash(password, hash.slice(0, 29)), hash);
  }
});

test('new passwords retain cost 10 and receive independent random salts', async () => {
  const password = 'New-account-test-42!';
  const first = await bcrypt.hash(password, 10);
  const second = await bcrypt.hash(password, 10);
  assert.equal(bcrypt.getRounds(first), 10);
  assert.notEqual(first, second);
  assert.equal(await bcrypt.compare(password, first), true);
  assert.equal(await bcrypt.compare('wrong-password', first), false);
});
